module freq_divbyodd(
    input clk, 
    input rst_n, 
    output clk_div
);
// Parameter declaration
parameter NUM_DIV = 5;
// Internal signal declaration
reg [2:0] cnt1, cnt2;
reg clk_div1, clk_div2;
// Combinational logic for positive edge clock divider
always @* begin
    if(cnt1 == ((NUM_DIV/2)-1))
        clk_div1 = ~clk_div1;
    else
        cnt1 = cnt1 + 1;
end
// Combinational logic for negative edge clock divider
always @* begin
    if(cnt2 == ((NUM_DIV/2)-1))
        clk_div2 = ~clk_div2;
    else
        cnt2 = cnt2 + 1;
end
// Output assignment
assign clk_div = clk_div1 | clk_div2;
endmodule
